CREATE TABLE ODOMetadata (key VARCHAR NOT NULL PRIMARY KEY, value BLOB NOT NULL);
CREATE TABLE Attachment (persistentIdentifier text NOT NULL PRIMARY KEY, containingTransactionHint text, context text, creationOrdinal integer NOT NULL, dataIdentifier text, dateAdded timestamp NOT NULL, dateModified timestamp NOT NULL, folder text, name text, perspective text, previewPNGData blob, size integer NOT NULL, task text);
CREATE TABLE Folder (persistentIdentifier text NOT NULL PRIMARY KEY, childrenCount integer NOT NULL, childrenCountActive integer NOT NULL, childrenState integer NOT NULL, creationOrdinal integer NOT NULL, dateAdded timestamp NOT NULL, dateHidden timestamp, dateModified timestamp NOT NULL, effectiveDateHidden timestamp, name text, noteXMLData blob, numberOfAvailableTasks integer NOT NULL, numberOfContainedTasks integer NOT NULL, numberOfDueSoonTasks integer NOT NULL, numberOfOverdueTasks integer NOT NULL, numberOfRemainingTasks integer NOT NULL, parent text, plainTextNote text, rank integer NOT NULL);
CREATE TABLE Task (persistentIdentifier text NOT NULL PRIMARY KEY, blocked integer NOT NULL, blockedByFutureStartDate integer NOT NULL, catchUpAutomatically integer NOT NULL, childrenCount integer NOT NULL, childrenCountActive integer NOT NULL, childrenCountAvailable integer NOT NULL, childrenCountCompleted integer NOT NULL, childrenState integer NOT NULL, completeWhenChildrenComplete integer NOT NULL, containingProjectContainsSingletons integer NOT NULL, containingProjectInfo text, containsNextTask integer NOT NULL, creationOrdinal integer NOT NULL, dateAdded timestamp NOT NULL, dateCompleted timestamp, dateDue datetime, dateHidden timestamp, dateModified timestamp NOT NULL, datePlanned datetime, dateToStart datetime, deferDateAlarmPolicyString text, dueDateAlarmPolicyString text, dueSoon integer NOT NULL, effectiveContainingProjectInfoActive integer NOT NULL, effectiveContainingProjectInfoRemaining integer NOT NULL, effectiveDateCompleted timestamp, effectiveDateDue timestamp, effectiveDateHidden timestamp, effectiveDatePlanned timestamp, effectiveDateToStart timestamp, effectiveFlagged integer NOT NULL, effectiveInInbox integer NOT NULL, estimatedMinutes integer, flagged integer NOT NULL, hasCompletedDescendant integer NOT NULL, hasFlaggedTaskInTree integer NOT NULL, hasUnestimatedLeafTaskInTree integer NOT NULL, inInbox integer NOT NULL, latestTimeToStartAlarmPolicyString text, maximumEstimateInTree integer, minimumEstimateInTree integer, name text, nextCloneIdentifier integer NOT NULL, nextTaskOfProjectInfo text, noteXMLData blob, overdue integer NOT NULL, parent text, plainTextNote text, plannedDateAlarmPolicyString text, projectInfo text, rank integer NOT NULL, repetitionAnchorDateKey text, repetitionRuleString text, repetitionScheduleTypeString text, sequential integer NOT NULL, sharedPlanObjectId integer NOT NULL, tagged integer NOT NULL);
CREATE TABLE TaskToTag (persistentIdentifier text NOT NULL PRIMARY KEY, creationOrdinal integer NOT NULL, dateAdded timestamp NOT NULL, dateModified timestamp NOT NULL, rankInTag blob, rankInTask blob NOT NULL, tag text, task text);
CREATE TABLE ProjectInfo (pk text NOT NULL PRIMARY KEY, containsSingletonActions integer NOT NULL, effectiveStatus text NOT NULL, folder text, folderEffectiveDateHidden timestamp, lastReviewDate timestamp, minimumDueDate timestamp, minimumPlannedDate timestamp, nextReviewDate timestamp, nextTask text, numberOfAvailableTasks integer NOT NULL, numberOfContainedTasks integer NOT NULL, numberOfDueSoonTasks integer NOT NULL, numberOfOverdueTasks integer NOT NULL, numberOfRemainingTasks integer NOT NULL, planOrdering integer NOT NULL, planProjectID text, reviewRepetitionString text, status text NOT NULL, task text, taskBlocked integer NOT NULL, taskBlockedByFutureStartDate integer NOT NULL, taskDateToStart timestamp, team text);
CREATE TABLE Context (persistentIdentifier text NOT NULL PRIMARY KEY, allowsNextAction integer NOT NULL, altitude real, availableTaskCount integer NOT NULL, childrenAreMutuallyExclusive integer NOT NULL, childrenCount integer NOT NULL, childrenCountActive integer NOT NULL, childrenState integer NOT NULL, containedTaskCount integer NOT NULL, creationOrdinal integer NOT NULL, dateAdded timestamp NOT NULL, dateHidden timestamp, dateModified timestamp NOT NULL, effectiveDateHidden timestamp, latitude real, localNumberOfDueSoonTasks integer NOT NULL, localNumberOfOverdueTasks integer NOT NULL, locationName text, longitude real, name text, nextTaskCount integer NOT NULL, noteXMLData blob, notificationFlags integer, parent text, participatesInMutualExclusion integer NOT NULL, plainTextNote text, radius real, rank integer NOT NULL, remainingTaskCount integer NOT NULL, tasksAreUserOrdered integer NOT NULL, totalNumberOfDueSoonTasks integer NOT NULL, totalNumberOfOverdueTasks integer NOT NULL);
